      directives: {
        "default-src": ["'self'"],
        "base-uri": ["'self'"],
        "frame-ancestors": ["'none'"],
        "object-src": ["'none'"],
        "script-src": ["'self'"],
        "style-src": ["'self'"],
        "img-src": ["'self'", "data:"],
        "connect-src": ["'self'"],
        "upgrade-insecure-requests": process.env.NODE_ENV === 'production' ? [] : null,
      },
    },
  })
);

app.use(requireHttps);

// ---- Body parsing with sane limits ----
app.use(express.json({ limit: '100kb', strict: true, type: 'application/json' }));
app.use(express.urlencoded({ extended: false, limit: '50kb' }));

// ---- Minimal request correlation id (helps logging without leaking internals) ----
app.use((req, res, next) => {
  const rid = req.get('x-request-id') || crypto.randomUUID();
  res.setHeader('x-request-id', rid);
  req.requestId = rid;
  next();
});

