// debugErrorHandler.js
'use strict';

/**
 * Debug-only Express error handler that returns full stack trace in JSON.
 * IMPORTANT: Only enable in local development on a trusted machine/network.
 */
function debugErrorHandler(err, req, res, next) { // eslint-disable-line no-unused-vars
  const status = Number.isInteger(err?.status) ? err.status
               : Number.isInteger(err?.statusCode) ? err.statusCode
               : 500;

  // Avoid caching error responses
  res.set('Cache-Control', 'no-store');

  res.status(status).json({
    error: {
      message: err?.message || 'Internal Server Error',
      name: err?.name,
      status,
      stack: err?.stack,          // full stack trace (insecure for non-local use)
      cause: err?.cause,          // may contain sensitive details
    },
    request: {
      method: req.method,
      path: req.originalUrl,
      requestId: req.id,          // if you attach one upstream
    },
  });
}

module.exports = { debugErrorHandler };
