// Uses Argon2id (recommended) with conservative, production-sensible defaults.
// Requires: npm i argon2  (officially maintained package)

'use strict';

const argon2 = require('argon2');

/**
 * Tunable parameters:
 * - memoryCost is in KiB (e.g., 64 * 1024 = 64 MiB)
 * - timeCost is iterations/passes
 * - parallelism should generally match available CPU cores, but keep modest for shared servers
 *
 * NOTE: You should benchmark on your target hardware and adjust to keep hashing ~100-300ms
 * per password (or per your risk/performance budget).
 */
const ARGON2_OPTIONS = Object.freeze({
  type: argon2.argon2id,
  memoryCost: 64 * 1024, // 64 MiB
  timeCost: 3,
  parallelism: 1,
  hashLength: 32,
});

/**
 * Hash a password using Argon2id.
 * @param {string} password - User-supplied password (plaintext).
 * @returns {Promise<string>} Encoded Argon2 hash string (includes salt + params).
 */
async function hashPassword(password) {
  if (typeof password !== 'string') {
    throw new TypeError('Password must be a string.');
  }
  // Positive validation: enforce a reasonable length range to reduce DoS risk.
  // (Adjust upper bound to your policy; 72 is bcrypt-specific, Argon2 can handle longer.)
  if (password.length < 8 || password.length > 256) {
    throw new RangeError('Password length must be between 8 and 256 characters.');
  }

  // argon2.hash generates a cryptographically secure random salt internally.
  return argon2.hash(password, ARGON2_OPTIONS);
}

/**
 * Verify a password against a stored Argon2 hash.
 * @param {string} storedHash - Encoded Argon2 hash from your DB.
 * @param {string} password - Candidate password (plaintext).
 * @returns {Promise<boolean>} True if valid, else false.
 */
async function verifyPassword(storedHash, password) {
  if (typeof storedHash !== 'string' || storedHash.length === 0) {
    throw new TypeError('storedHash must be a non-empty string.');
  }
  if (typeof password !== 'string') {
    throw new TypeError('Password must be a string.');
  }

  // argon2.verify parses parameters from storedHash and uses constant-time comparison internally.
  return argon2.verify(storedHash, password);
}

module.exports = {
  hashPassword,
  verifyPassword,
  ARGON2_OPTIONS,
};
