```js
// logger.js
import pino from "pino";

const isProd = process.env.NODE_ENV === "production";

// Remove CR/LF/TAB and other control chars to prevent log forging/injection.
// Also cap length to avoid log flooding.
export function sanitizeForLog(value, maxLen = 200) {
  if (value === null || value === undefined) return undefined;
  const s = String(value);

  // Replace ASCII control chars (0x00-0x1F, 0x7F) with safe placeholders
  const cleaned = s.replace(/[\u0000-\u001F\u007F]/g, "_");

  return cleaned.length > maxLen ? cleaned.slice(0, maxLen) + "…" : cleaned;
}

export const logger = pino({
  level: process.env.LOG_LEVEL || (isProd ? "info" : "debug"),
  redact: {
    // Prevent accidental secret leakage
    paths: [
      "req.headers.authorization",
      "req.headers.cookie",
      "password",
      "newPassword",
      "token",
      "refreshToken",
      "otp",
    ],
    remove: true,
  },
  base: {
    service: process.env.SERVICE_NAME || "webapp",
    env: process.env.NODE_ENV || "development",
  },
  // Keep logs machine-parseable; avoid custom string formatting.
});
```

