// error-handler.js
'use strict';

const crypto = require('crypto');

/**
 * Global Express error handler (must be registered AFTER all routes/middleware).
 *
 * Assumptions:
 * - If a DB transaction exists, it is attached to req.tx and supports rollback().
 * - A logger is available at req.log (pino/bunyan/winston-like) OR console is used as fallback.
 * - You do NOT leak stack traces to clients; you return a generic message with a correlation id.
 */
function globalErrorHandler(err, req, res, next) { // eslint-disable-line no-unused-vars
  // Fail closed: if headers already sent, delegate to Express' default handler
  // (still avoids writing partial/contradictory responses).
  if (res.headersSent) return next(err);

  const correlationId =
    req.id ||
    req.headers['x-request-id'] ||
    crypto.randomUUID();

  // Ensure we never throw from the error handler (A10: fail closed)
  (async () => {
    // Roll back transaction if present
    if (req.tx && typeof req.tx.rollback === 'function') {
      try {
        await req.tx.rollback();
      } catch (rollbackErr) {
        // Log rollback failure internally; do not expose to client
        safeLog(req, 'error', 'transaction_rollback_failed', {
          correlationId,
          rollbackErrorName: rollbackErr?.name,
          rollbackErrorMessage: rollbackErr?.message,
        });
      }
    }

    // Internal logging with context; avoid logging secrets/PII
    safeLog(req, 'error', 'unhandled_request_error', {
      correlationId,
      method: req.method,
      path: req.originalUrl || req.url,
      ip: req.ip,
      userId: req.user?.id, // only if you attach authenticated user server-side
      errorName: err?.name,
      errorMessage: err?.message,
      // Stack is internal-only; ensure logs are access-controlled
      stack: err?.stack,
    });

    // Generic client response (no stack trace / no internal details)
    res
      .status(500)
      .set({
        'Content-Type': 'application/json; charset=utf-8',
        'Cache-Control': 'no-store',
        'X-Content-Type-Options': 'nosniff',
      })
      .json({
        error: 'Internal Server Error',
        requestId: correlationId,
      });
  })().catch((handlerErr) => {
    // Absolute last resort: fail closed with minimal response
    try {
      safeLog(req, 'error', 'global_error_handler_failed', {
        correlationId,
        handlerErrorName: handlerErr?.name,
        handlerErrorMessage: handlerErr?.message,
      });
      res.status(500).json({ error: 'Internal Server Error', requestId: correlationId });
    } catch {
      // If even this fails, end the response.
      res.end();
    }
  });
}

function safeLog(req, level, event, meta) {
  // Prevent log injection by ensuring meta is structured (not concatenated strings)
  const logger = req.log || console;
  const payload = { event, ...meta };

  // Prefer structured logging methods if present
  if (typeof logger[level] === 'function') {
    logger[level](payload);
  } else if (typeof logger.log === 'function') {
    logger.log(level, payload);
  }
}

module.exports = { globalErrorHandler };
