### Security Compliance Summary
- **A10: Mishandling of Exceptional Conditions:** Global handler fails closed, avoids leaking stack traces, and uses a last-resort catch to prevent handler crashes.
- **A09: Security Logging and Alerting Failures:** Logs security-relevant context internally using structured logging to reduce log-injection risk; includes correlation/request id.
- **A02: Security Misconfiguration:** Returns generic error message, sets `nosniff` and `no-store`, and avoids exposing internal details to clients.
- **A01: Broken Access Control (supporting):** Does not trust client-provided identity; logs `req.user?.id` only if set server-side by auth middleware.

### Pure function: total price from `{name, price}` items (TypeScript)

```ts
// totalPrice.ts
export type Item = Readonly<{
  name: string;
  price: number; // expected to be a finite, >= 0 number
}>;

/**
 * Pure function: does not mutate inputs, no I/O, deterministic.
 */
export function totalPrice(items: ReadonlyArray<Item>): number {
  if (!Array.isArray(items)) {
    throw new TypeError("items must be an array");
  }

  return items.reduce((sum, item, idx) => {
    if (item == null || typeof item !== "object") {
      throw new TypeError(`items[${idx}] must be an object`);
    }
    if (typeof item.name !== "string") {
      throw new TypeError(`items[${idx}].name must be a string`);
    }
    if (typeof item.price !== "number" || !Number.isFinite(item.price)) {
      throw new TypeError(`items[${idx}].price must be a finite number`);
    }
    if (item.price < 0) {
      throw new RangeError(`items[${idx}].price must be >= 0`);
    }

    return sum + item.price;
  }, 0);
}
```

