### 3) Validation middleware (deterministic, strict, size-limited)
`middleware/validatePrompt.js`
```js
import Ajv from "ajv";
import addFormats from "ajv-formats";
import schema from "../schema/prompt.schema.json" assert { type: "json" };

const ajv = new Ajv({
  allErrors: true,
  strict: true,
  allowUnionTypes: false,
  removeAdditional: false // we reject extras instead of silently removing
});
addFormats(ajv);

const validate = ajv.compile(schema);

// Hard limits to prevent unbounded consumption (LLM10)
const MAX_BODY_BYTES = 16 * 1024; // 16KB total JSON payload

export function validatePromptInput(req, res, next) {
  // Enforce content-type
  const ct = (req.headers["content-type"] || "").toLowerCase();
  if (!ct.includes("application/json")) {
    return res.status(415).json({ error: "Content-Type must be application/json" });
  }

  // Enforce size limit using Content-Length when present (still keep server body limit too)
  const len = req.headers["content-length"];
  if (len && Number(len) > MAX_BODY_BYTES) {
    return res.status(413).json({ error: "Payload too large" });
  }

  const data = req.body;

  // Deterministic schema validation
  const ok = validate(data);
  if (!ok) {
    // Do not echo raw user input back; return structured errors only (LLM02)
    return res.status(400).json({
      error: "Invalid request",
      details: validate.errors?.map(e => ({
        path: e.instancePath || "/",
        message: e.message
      }))
    });
  }

  // Normalize into an internal safe shape (defense-in-depth)
  req.validatedPrompt = {
    prompt: data.prompt.trim(),
    userId: data.userId,
    metadata: data.metadata ?? {}
  };

  return next();
}
```

