### 2) Vault client (runtime secret retrieval)
Use Vault’s Kubernetes auth / AWS IAM auth / OIDC so you don’t store long-lived tokens in code.

```ts
// vault.ts
import fetch from "node-fetch";
import assert from "node:assert";

const VAULT_ADDR = process.env.VAULT_ADDR; // e.g. https://vault.service:8200
assert(VAULT_ADDR, "VAULT_ADDR is required");

// Example assumes Vault Agent injects a short-lived token into env or file.
// Prefer: Vault Agent + auto-auth + templating, or workload identity.
const VAULT_TOKEN = process.env.VAULT_TOKEN;
assert(VAULT_TOKEN, "VAULT_TOKEN is required (use short-lived token via agent/identity)");

export async function readVaultSecret(path: string): Promise<Record<string, string>> {
  // Strict allowlist of secret paths to prevent arbitrary reads (LLM01/LLM06)
  const ALLOWED = new Set(["secret/data/llm/openai"]);
  if (!ALLOWED.has(path)) throw new Error("Secret path not allowed");

  const res = await fetch(`${VAULT_ADDR}/v1/${path}`, {
    method: "GET",
    headers: {
      "X-Vault-Token": VAULT_TOKEN,
      "Accept": "application/json",
    },
  });

  if (!res.ok) throw new Error(`Vault read failed: ${res.status}`);
  const json = await res.json();

  // KV v2 shape: { data: { data: { ... } } }
  const data = json?.data?.data;
  if (!data || typeof data !== "object") throw new Error("Unexpected Vault response");
  return data as Record<string, string>;
}
```

