  /sk-[A-Za-z0-9]{20,}/g,                 // common API key shape example
  /-----BEGIN (RSA|EC|OPENSSH) PRIVATE KEY-----/g,
  /\bAKIA[0-9A-Z]{16}\b/g,                // AWS access key id pattern
