  /system prompt/i,
  /developer message/i,
];

export type GuardrailResult =
  | { ok: true; output: string }
  | { ok: false; reason: string };

export function inspectAndRedact(output: string): GuardrailResult {
  // Block obvious prompt-injection artifacts (LLM01/LLM07)
  if (INJECTION_MARKERS.some(r => r.test(output))) {
    return { ok: false, reason: "Potential prompt-injection content detected" };
