### Types

```ts
export type AuthContext = {
  tenantId: string;          // from session/JWT, not request body
  userId: string;            // from session/JWT
  roles: string[];           // from session/JWT
};

export type FilterOp = "eq" | "in" | "contains" | "gte" | "lte";

export type MetadataFilter =
  | { field: "source" | "lang"; op: "eq"; value: string }
  | { field: "tags"; op: "contains"; value: string }
  | { field: "created_at"; op: "gte" | "lte"; value: string } // ISO date
  | { field: "doc_id"; op: "eq"; value: string };
```

### Filter validation + SQL builder (allowlist)

```ts
function assertUuid(v: string): void {
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v)) {
    throw new Error("Invalid UUID");
  }
}

function assertIsoDate(v: string): void {
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) throw new Error("Invalid ISO date");
}

type SqlFrag = { text: string; values: any[] };

function buildMetadataWhere(filters: MetadataFilter[]): SqlFrag {
  const clauses: string[] = [];
  const values: any[] = [];

  for (const f of filters) {
    switch (f.field) {
      case "source":
      case "lang": {
        if (f.op !== "eq") throw new Error("Invalid op for field");
        values.push(f.value);
        // metadata->>'field' = $n
        clauses.push(`(metadata->>'${f.field}') = $${values.length}`);
        break;
      }
      case "tags": {
        if (f.op !== "contains") throw new Error("Invalid op for tags");
        values.push(f.value);
        // metadata->'tags' ? 'value'
        clauses.push(`(metadata->'tags') ? $${values.length}`);
        break;
      }
      case "created_at": {
        if (f.op !== "gte" && f.op !== "lte") throw new Error("Invalid op for created_at");
        assertIsoDate(f.value);
        values.push(f.value);
        clauses.push(`created_at ${f.op === "gte" ? ">=" : "<="} $${values.length}::timestamptz`);
        break;
      }
      case "doc_id": {
        if (f.op !== "eq") throw new Error("Invalid op for doc_id");
        assertUuid(f.value);
        values.push(f.value);
        clauses.push(`doc_id = $${values.length}::uuid`);
        break;
      }
      default:
        // Exhaustiveness
        throw new Error("Unsupported filter field");
    }
  }

  return {
    text: clauses.length ? ` AND ${clauses.join(" AND ")}` : "",
    values
  };
}
```

